/**
 * @license Apache-2.0
 * @s2c/export-gerber — M20b Independent Round-Trip Validation Test Suite.
 *
 * Verifies that the Gerber RS-274X and Excellon drill files generated by @s2c/export-gerber
 * can be successfully and independently parsed by third-party parsers:
 * 1) @hpcreery/tracespace-parser (v5.0.4) — AST parser from tracespace
 * 2) gerber-parser (v4.2.7) — Streaming Gerber/Excellon parser
 */

import { createParser } from "@hpcreery/tracespace-parser";
import { synthesizeSketch } from "@s2c/arduino";
import { ARDUINO_UNO_R3_SHIELD_OUTLINE } from "@s2c/footprints";
import { placeCircuit, routeCircuit } from "@s2c/pcb-layout";
import gerberParser from "gerber-parser";
import { describe, expect, it } from "vitest";
import { exportGerber } from "../src/index.js";

describe("M20b: Independent Gerber & Drill Parser Round-Trip Validation", () => {
  const BLINK_CODE = `
    const int ledPin = 13;
    void setup() {
      pinMode(ledPin, OUTPUT);
    }
    void loop() {
      digitalWrite(ledPin, HIGH);
      delay(1000);
      digitalWrite(ledPin, LOW);
      delay(1000);
    }
  `;

  const POT_CODE = `
    const int potPin = A0;
    const int ledPin = 9;
    void setup() {
      pinMode(ledPin, OUTPUT);
    }
    void loop() {
      int val = analogRead(potPin);
      analogWrite(ledPin, val / 4);
    }
  `;

  const HC_SR04_CODE = `
    const int trigPin = 9;
    const int echoPin = 10;
    const int ledPin = 13;
    void setup() {
      pinMode(trigPin, OUTPUT);
      pinMode(echoPin, INPUT);
      pinMode(ledPin, OUTPUT);
    }
    void loop() {
      digitalWrite(trigPin, LOW);
      delayMicroseconds(2);
      digitalWrite(trigPin, HIGH);
      delayMicroseconds(10);
      digitalWrite(trigPin, LOW);
      long duration = pulseIn(echoPin, HIGH);
      if (duration < 1000) {
        digitalWrite(ledPin, HIGH);
      } else {
        digitalWrite(ledPin, LOW);
      }
    }
  `;

  function buildLayout(code: string) {
    const syn = synthesizeSketch(code, { boardId: "ARDUINO_UNO_R3" });
    const placed = placeCircuit(syn.circuit, ARDUINO_UNO_R3_SHIELD_OUTLINE);
    const routed = routeCircuit(placed.layout, syn.circuit, { gridPitchMm: 0.635 });
    return routed.layout;
  }

  // Corpus 1: Blink Circuit
  it("successfully round-trips Corpus 1 (Blink) through independent parser @hpcreery/tracespace-parser", () => {
    const layout = buildLayout(BLINK_CODE);
    const result = exportGerber(layout, { boardName: "blink" });

    // 1. Verify every file in the 8-file set parses cleanly into an AST without throwing
    for (const [filename, content] of Object.entries(result.files)) {
      const parser = createParser();
      expect(() => parser.feed(content)).not.toThrow();
      const ast = parser.result();
      expect(ast).toBeDefined();
      expect(ast.type).toBe("root");
      expect(ast.children.length).toBeGreaterThan(0);

      if (filename.endsWith(".drl")) {
        expect(ast.filetype).toBe("drill");
      } else {
        expect(ast.filetype).toBe("gerber");
      }
    }

    // 2. Drill file round-trip analysis
    const drillParser = createParser();
    drillParser.feed(result.drill);
    const drillAst = drillParser.result();

    const drillHits = drillAst.children.filter((node) => node.type === "graphic");
    const drillToolDefs = drillAst.children.filter((node) => node.type === "toolDefinition");

    expect(drillHits.length).toBe(result.metrics.drillHoleCount);
    expect(drillHits.length).toBe(layout.vias.length + 38); // 3 vias + 38 THT pins
    expect(drillToolDefs.length).toBeGreaterThan(0);

    // 3. Top copper layer round-trip analysis
    const gtlParser = createParser();
    gtlParser.feed(result.topCopper);
    const gtlAst = gtlParser.result();

    const toolDefs = gtlAst.children.filter((node) => node.type === "toolDefinition");
    expect(toolDefs.length).toBe(result.metrics.aperturesDefinedTopCopper);

    const graphics = gtlAst.children.filter((node) => node.type === "graphic") as Array<{
      type: string;
      graphic?: string;
    }>;
    const flashes = graphics.filter((g) => g.graphic === "shape");
    const traceMoves = graphics.filter((g) => g.graphic === "move");
    const traceSegments = graphics.filter((g) => g.graphic === "segment");

    // Flashes must equal pads on top layer + vias
    expect(flashes.length).toBe(result.metrics.topPadCount + result.metrics.viaCount);
    // Trace moves must equal top traces routed
    expect(traceMoves.length).toBe(result.metrics.topCopperTraceCount);
    expect(traceSegments.length).toBeGreaterThan(0);
  });

  // Corpus 2: Potentiometer Circuit
  it("successfully round-trips Corpus 2 (Potentiometer) through independent parser @hpcreery/tracespace-parser", () => {
    const layout = buildLayout(POT_CODE);
    const result = exportGerber(layout, { boardName: "pot" });

    for (const [_filename, content] of Object.entries(result.files)) {
      const parser = createParser();
      expect(() => parser.feed(content)).not.toThrow();
      const ast = parser.result();
      expect(ast.type).toBe("root");
      expect(ast.children.length).toBeGreaterThan(0);
    }

    const drillParser = createParser();
    drillParser.feed(result.drill);
    const drillAst = drillParser.result();
    const drillHits = drillAst.children.filter((node) => node.type === "graphic");
    expect(drillHits.length).toBe(result.metrics.drillHoleCount);
  });

  // Corpus 3: HC-SR04 Circuit
  it("successfully round-trips Corpus 3 (HC-SR04) through independent parser @hpcreery/tracespace-parser", () => {
    const layout = buildLayout(HC_SR04_CODE);
    const result = exportGerber(layout, { boardName: "hc_sr04" });

    for (const [_filename, content] of Object.entries(result.files)) {
      const parser = createParser();
      expect(() => parser.feed(content)).not.toThrow();
      const ast = parser.result();
      expect(ast.type).toBe("root");
      expect(ast.children.length).toBeGreaterThan(0);
    }

    const drillParser = createParser();
    drillParser.feed(result.drill);
    const drillAst = drillParser.result();
    const drillHits = drillAst.children.filter((node) => node.type === "graphic");
    expect(drillHits.length).toBe(result.metrics.drillHoleCount);
  });

  // Second independent parser: streaming gerber-parser
  it("successfully parses top copper with streaming gerber-parser and matches feature counts", async () => {
    const layout = buildLayout(BLINK_CODE);
    const result = exportGerber(layout, { boardName: "blink" });

    const p = gerberParser({});
    let toolCount = 0;
    let flashCount = 0;
    let moveCount = 0;
    let intCount = 0;

    await new Promise<void>((resolve, reject) => {
      p.on("data", (chunk: { type: string; op?: string }) => {
        if (chunk.type === "tool") toolCount++;
        if (chunk.type === "op") {
          if (chunk.op === "flash") flashCount++;
          if (chunk.op === "move") moveCount++;
          if (chunk.op === "int") intCount++;
        }
      });
      p.on("error", reject);
      p.on("finish", () => resolve());
      p.write(result.topCopper);
      p.end();
    });

    expect(toolCount).toBe(result.metrics.aperturesDefinedTopCopper);
    expect(flashCount).toBe(result.metrics.topPadCount + result.metrics.viaCount);
    expect(moveCount).toBe(result.metrics.topCopperTraceCount);
    expect(intCount).toBeGreaterThan(0);
  });
});
